-- Meeting booking tables for BTSCALLS.
--   MeetSlot        : one row per bookable time slot (generated by the API from config.json)
--   MeetBooking     : one row per booked meeting (main table), linked to MeetSlot
--   MeetBlockedDate : dates the admin has closed for bookings
-- Safe to run more than once.
USE BTSCALLS;
GO

IF OBJECT_ID(N'dbo.MeetSlot', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.MeetSlot (
        SlotId      INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_MeetSlot PRIMARY KEY,
        SlotDate    DATE         NOT NULL,
        StartTime   CHAR(5)      NOT NULL,   -- HH:MM, 24 hour
        EndTime     CHAR(5)      NOT NULL,   -- HH:MM, 24 hour
        Capacity    INT          NOT NULL CONSTRAINT DF_MeetSlot_Capacity DEFAULT (1),
        IsActive    BIT          NOT NULL CONSTRAINT DF_MeetSlot_IsActive DEFAULT (1),
        CreatedAt   DATETIME2(0) NOT NULL CONSTRAINT DF_MeetSlot_CreatedAt DEFAULT (SYSDATETIME()),
        CONSTRAINT UQ_MeetSlot_DateStart UNIQUE (SlotDate, StartTime),
        CONSTRAINT CK_MeetSlot_Capacity CHECK (Capacity >= 1)
    );
END
GO

IF OBJECT_ID(N'dbo.MeetBooking', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.MeetBooking (
        BookingId    INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_MeetBooking PRIMARY KEY,
        BookingRef   VARCHAR(20)    NOT NULL CONSTRAINT UQ_MeetBooking_Ref UNIQUE,
        SlotId       INT            NOT NULL CONSTRAINT FK_MeetBooking_MeetSlot REFERENCES dbo.MeetSlot (SlotId),
        CustomerName NVARCHAR(100)  NOT NULL,
        Email        NVARCHAR(150)  NOT NULL,
        Phone        VARCHAR(20)    NULL,
        Company      NVARCHAR(150)  NULL,
        Purpose      NVARCHAR(500)  NULL,
        Status       VARCHAR(20)    NOT NULL CONSTRAINT DF_MeetBooking_Status DEFAULT ('Booked'),
        Source       VARCHAR(20)    NOT NULL CONSTRAINT DF_MeetBooking_Source DEFAULT ('Website'),
        CreatedAt    DATETIME2(0)   NOT NULL CONSTRAINT DF_MeetBooking_CreatedAt DEFAULT (SYSDATETIME()),
        CancelledAt  DATETIME2(0)   NULL,
        CONSTRAINT CK_MeetBooking_Status CHECK (Status IN ('Booked', 'Cancelled')),
        CONSTRAINT CK_MeetBooking_Source CHECK (Source IN ('Website', 'Admin'))
    );
    CREATE INDEX IX_MeetBooking_Slot_Status ON dbo.MeetBooking (SlotId, Status);
END
GO

IF OBJECT_ID(N'dbo.MeetBlockedDate', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.MeetBlockedDate (
        BlockedDate DATE          NOT NULL CONSTRAINT PK_MeetBlockedDate PRIMARY KEY,
        Reason      NVARCHAR(200) NULL,
        CreatedAt   DATETIME2(0)  NOT NULL CONSTRAINT DF_MeetBlockedDate_CreatedAt DEFAULT (SYSDATETIME())
    );
END
GO

-- Handy view for reports: every booking with its slot date and time.
CREATE OR ALTER VIEW dbo.vw_MeetBookingDetail AS
SELECT b.BookingId, b.BookingRef, s.SlotDate, s.StartTime, s.EndTime,
       b.CustomerName, b.Email, b.Phone, b.Company, b.Purpose,
       b.Status, b.Source, b.CreatedAt, b.CancelledAt
FROM dbo.MeetBooking b
JOIN dbo.MeetSlot s ON s.SlotId = b.SlotId;
GO
